  /*Definition: librarian scans a user ID and a book barcode to process a borrowing request.
   *Precondition: The system first checks whether the user exists, is not suspended, and still has borrowing quota.
   *Postcondition:Then it confirms the selected copy is available (or reserved for this same user), creates a new loan record, sets the due date by user type, updates book status to loaned, and returns true when the checkout succeeds.*/
  borrowBook(uid: string, barcode: string): boolean {
    /*Definition Start*/
    let u: User = l({
      logic: () =>
        getRepository(User).find(
          (o: any) =>
            l({
              logic: () => o.UserID === uid,
              description: "o.UserID=uid",
            }).build().pass,
        ),
      description: "User.allInstance()->any(o|o.UserID=uid)",
    }).build().pass;
    let c: BookCopy = l({
      logic: () =>
        getRepository(BookCopy).find(
          (o: any) =>
            l({
              logic: () => o.Barcode === barcode,
              description: "o.Barcode=barcode",
            }).build().pass,
        ),
      description: "BookCopy.allInstance()->any(o|o.Barcode=barcode)",
    }).build().pass;
    let b: Book = l({
      logic: () => c.BookBelongs,
      description: "c.BookBelongs",
    }).build().pass;
    let r: Reserve = l({
      logic: () =>
        c.ReservationRecord.find(
          (o: any) =>
            l({
              logic: () => o.ReservedUser === u,
              description: "o.ReservedUser=u",
            }).build().pass,
        ),
      description: "c.ReservationRecord->any(o|o.ReservedUser=u)",
    }).build().pass;
    /*Definition End*/

    /*Precondition Start*/
    const { errorMessage: preconditionErrorMessage, pass: isPreconditionPass } =
      l({
        logic: () => StandardOPs.oclIsUndefined(u) === false,
        description: "u.oclIsUndefined()=false",
      })
        .and({
          logic: () => u.BorrowStatus === BorrowStatus.NORMAL,
          description: "u.BorrowStatus=BorrowStatus::NORMAL",
        })
        .and({
          logic: () => u.LoanedNumber < 5,
          description: "u.LoanedNumber<5",
        })
        .and({
          logic: () => StandardOPs.oclIsUndefined(c) === false,
          description: "c.oclIsUndefined()=false",
        })
        .and({
          logic: () => c.Status === CopyStatus.AVAILABLE,
          description: "c.Status=CopyStatus::AVAILABLE",
        })
        .or({
          logic: () => StandardOPs.oclIsUndefined(r) === false,
          description: "r.oclIsUndefined()=false",
        })
        .and({
          logic: () => r.ReservedUser === u,
          description: "r.ReservedUser=u",
        })
        .build();
    if (!isPreconditionPass) {
      throw new PreconditionError(preconditionErrorMessage);
    }
    /*Precondition End*/

    /*Postcondition Start*/
    let loan: Loan;
    return l({
      execute: () => (loan = new Loan()),
      description: "loan.oclIsNew()",
    })
      .and({
        execute: () => getRepository(Loan).push(loan),
        description: "Loan.allInstance()->includes(loan)",
      })
      .and({
        execute: () => (loan.LoanedUser = u),
        description: "loan.LoanedUser=u",
      })
      .and({
        execute: () => (loan.LoanedCopy = c),
        description: "loan.LoanedCopy=c",
      })
      .and({
        execute: () => (loan.IsReturned = false),
        description: "loan.IsReturned=false",
      })
      .and({
        execute: () => (loan.RenewedTimes = 0),
        description: "loan.RenewedTimes=0",
      })
      .and({
        execute: () => u.LoanedBook.push(loan),
        description: "u.LoanedBook->includes(loan)",
      })
      .and({
        execute: () => c.LoanedRecord.push(loan),
        description: "c.LoanedRecord->includes(loan)",
      })
